 if(canAct(state,u)&&t?.team==='object'&&ui.mode!=='search'&&validTarget(state,u,t,'search'))ui.mode='search';if(canAct(state,u)&&t?.team==='civilian'&&ui.mode!=='rescue'&&validTarget(state,u,t,'rescue'))ui.mode='rescue';
