window.AshenCrown=Object.freeze({version:VERSION,audio:()=>audio.diagnostics(),snapshot:()=>structuredClone(state),view:()=>({hubCamera:structuredClone(hubCamera.current),camera:structuredClone(renderer.camera),selected:ui.selected,mode:ui.mode,busy:ui.busy||frontierWalking,zoom:renderer.zoom,tileResolution:TILE,nativeTileResolution:NATIVE_TILE,nativeSpriteResolution:NATIVE_SPRITE,portraitResolution:PORTRAIT_SIZE,ranges:renderer.ranges?.()||[],drawnRanges:renderer.drawnRanges||0,preview:ui.preview??null,phaseConfirm:ui.phaseConfirm,menu:ui.menu,pendingMove:ui.pendingMove?structuredClone(ui.pendingMove):null,movement:ui.movement,reduced:ui.reduced,animation:renderer.diagnostics()}),tileCenter:(x,y)=>renderer.tileCenter(x,y)});

// v0.4 feedback: classic SRPG dialogue window — painted bust overlapping a translucent box, name in
// amber, tap anywhere to advance; only Auto/Skip stay on screen (top-right).
function renderStory(){clearTimeout(autoTimer);const l=storyLine(state),n=state.narrative;if(!l){$('#story-root').innerHTML='';return;}ui.menu=null;$('#unit-popover').hidden=true;if(l.world){renderWorldStory(l,n);return;}const staged=l.stage&&!n.active.key.startsWith('npc:');const speaker=findUnit(state,l.speaker)||SPEAKERS[l.speaker]||{id:'boss',name:'적'},name=l.name||speaker.ko||speaker.name;
 $('#story-root').innerHTML=`<section class="dialogue-backdrop ${staged?'staged-scene':'in-place-dialogue'}" role="dialog" aria-modal="true" aria-label="스토리 대화 · 화면을 누르면 다음" data-do="story-next">${staged?'<canvas id="scene-stage" width="1024" height="768" aria-label="인물들이 대화하는 장면"></canvas>':''}<div class="story-controls"><button data-do="story-auto" class="${n.auto?'on':''}" aria-pressed="${n.auto}">자동</button><button data-do="story-skip">스킵</button></div><div class="dialogue-panel ${ui.reduced?'reduced':''}" data-expression="${l.expression}"><canvas class="story-portrait story-bust" width="720" height="880" data-sprite="${esc(speaker.id)}" data-bust="1" aria-label="${esc(name)}"></canvas><div class="dialogue-copy"><h3 class="dialogue-name">${esc(name)}</h3><p class="dialogue-text">${esc(l.text)}</p></div><span class="dialogue-next" aria-hidden="true"></span><span class="sr-only">${n.active.index+1} / ${STORY[n.active.key].length}</span></div></section>`;const face=$('#story-root [data-sprite]');if(face)face.dataset.expression=l.expression;if(n.auto)autoTimer=setTimeout(()=>{if(!$('#modal-root').children.length)dispatch('story-next');},Math.max(2600,l.text.length*75));}
// v0.5 world-map interlude (D-052): the chronicle line narrates over the map; the card names the region.
function renderWorldStory(l,n){const k=`${n.active.key}:${n.active.index}`;if(worldStart.key!==k)worldStart={key:k,time:performance.now()};const c=l.world.card;
 $('#story-root').innerHTML=`<section class="dialogue-backdrop world-scene" role="dialog" aria-modal="true" aria-label="세계 지도 · 화면을 누르면 다음" data-do="story-next"><canvas id="world-stage" aria-label="에르디아 세계 지도"></canvas>${c?`<div class="world-card"><span class="eyebrow">${esc(c.act)}</span><h2>${esc(c.region)}</h2><p>${esc(c.place)}</p></div>`:''}<div class="story-controls"><button data-do="story-auto" class="${n.auto?'on':''}" aria-pressed="${n.auto}">자동</button><button data-do="story-skip">스킵</button></div><div class="dialogue-panel world-panel ${ui.reduced?'reduced':''}"><div class="dialogue-copy"><h3 class="dialogue-name">연대기</h3><p class="dialogue-text">${esc(l.text)}</p></div><span class="dialogue-next" aria-hidden="true"></span><span class="sr-only">${n.active.index+1} / ${STORY[n.active.key].length}</span></div></section>`;
 if(n.auto)autoTimer=setTimeout(()=>{if(!$('#modal-root').children.length)dispatch('story-next');},Math.max(3200,l.text.length*80));}
// v0.6 faction relations (D-055 Q3): stages, not numbers; banners appear once met.
function showFactions(){const rows=factionRows(state.campaign).map(r=>`<article class="faction-row ${r.met?'':'unmet'}" style="--banner:${r.color}"><h3><span class="banner-chip"></span>${r.met?esc(r.name):'아직 만나지 않은 세력'}</h3>${r.met?`<p class="faction-stage stage-${r.stage.id}"><b>${r.stage.ko}</b> · ${esc(r.stage.note)}</p><p class="muted">지도자 ${esc(r.leader)} · «${esc(r.motto)}»</p>`:'<p class="muted">이야기에서 만나면 관계가 표시됩니다.</p>'}</article>`).join('');
 modal('세력 관계',`<div class="faction-list">${rows}</div><p class="muted">관계는 경계 · 중립 · 신뢰 · 동맹 네 단계로 바뀝니다. 선택과 전투 결과가 반영됩니다.</p>`,'');}
function showWorldMap(){modal('세계 지도 · 에르디아',`<canvas id="world-view" class="world-view" aria-label="에르디아 세계 지도"></canvas><p class="muted">지명과 세력권은 이야기에서 만난 뒤 지도에 나타납니다.</p>`,'');}
function STORY_LENGTH(key){return key.endsWith('intro')?state.missionId===1?6:4:state.missionId===3&&key.endsWith('end')?4:key.endsWith('capture')?4:key.endsWith('bond')?4:key.endsWith('end')?3:key.endsWith('boss')?3:key==='defeat'?1:2;}
function showAudio(){modal('Original Music',`<p>${esc(audio.diagnostics().track)} · ${esc(audio.status)}</p><label>BGM <input id="music-volume" type="range" min="0" max="1" step=".05" value="${audio.prefs.music}"></label><label>SFX <input id="sfx-volume" type="range" min="0" max="1" step=".05" value="${audio.prefs.sfx}"></label><label><input id="audio-muted" type="checkbox" ${audio.prefs.muted?'checked':''}>Mute</label><label><input id="audio-paused" type="checkbox" ${audio.prefs.paused?'checked':''}>Music Pause</label><p>직접 작성한 악보와 브라우저 합성음 · 외부 샘플 없이 오프라인 재생.</p>`,'');}
function showAppearance(){modal('Character Appearance',`<p>에릭은 LV 5에 Advanced 의상으로 성장합니다. 외형 시범이며 전직 능력은 후속 버전에서 추가합니다.</p><div class="appearance-grid">${HEROES.map(h=>{const u=findUnit(state,h.id);return `<article><h3>${u.name} · Tier ${u.appearanceTier}</h3>${portrait(u)}${u.id==='eric'?'<canvas class="portrait" width="256" height="256" data-tier-preview="2"></canvas><p>Advanced Preview · LV 5</p>':'<p>Advanced / Elite 의상은 후속 제작</p>'}</article>`;}).join('')}</div>`,'');paintPortraits();const c=$('[data-tier-preview]'),adv={...findUnit(state,'eric'),appearanceTier:2,level:Math.max(5,findUnit(state,'eric').level)};if(drawPaintedHead(c.getContext('2d'),adv))c.style.imageRendering='auto';else drawPortrait(c.getContext('2d'),adv);}

function questExplore(){const f=state.frontier,m=missionOf(state),next=MISSIONS[state.missionId+1];if(f.interior)return `<b>${esc(currentHub(state).name)}</b><p>${INTERIORS[f.interior]?.generic?'보물상자를 찾아보자.':'주인에게 말을 걸어 거래하자.'}</p>`;
 if(f.phase==='aftermath')return `<b>전투 후 정비</b><p>${state.missionId===4&&!state.practice&&!state.campaign.choices?.m04_records_choice?'성채 기록을 어떻게 할지 정하자.':state.missionId===7&&needsDeserters()?'붙잡은 탈영병의 처분을 정하자.':state.missionId===6&&!state.practice&&!state.campaign.choices?.m06_oath?'재의 맹세: 군단의 맹세를 정하자.':next?`동료들과 이야기한 뒤 출발: ${esc(next.title)}${state.missionId===6?' · ACT II 세 개의 깃발':''}`:'ACT II 전반 계속 · M09 자유의 도시 — 다음 업데이트'}</p>`;
 return `<b>${esc(m.title)}</b><p>광장 동쪽 · 리아와 작전 회의</p><p class="quest-opt">${f.events.some(k=>k.endsWith(':aren'))?'✓':'◇'} 아렌 · ${f.visited[f.hub].includes('forge')?'✓':'◇'} 무기점 · ${f.visited[f.hub].includes('shop')?'✓':'◇'} 도구점</p>`;}
function turnLabel(s){const m=missionOf(s),limit=m.turnLimit,t=String(s.turn).padStart(2,'0');return limit?`턴 ${t} / ${limit}`:`턴 ${t} · 권장 ${m.par}`;}
function showRecordsChoice(){if(state.missionId!==4||state.practice||state.frontier?.phase!=='aftermath'||state.campaign.choices?.m04_records_choice)return;modal('기록의 행방',`<p>성채에서 확보한 보급 장부를 어떻게 다룰까요? 어느 쪽을 골라도 이야기는 이어지며, 이후 명령의 문구와 동료의 반응이 달라집니다.</p>`,`<button class="primary" data-do="records-pick" data-id="kept">원본을 군단이 보관한다</button><button class="primary" data-do="records-pick" data-id="reported">사본을 군령부에 정식 보고한다</button><button data-do="close-modal">조금 더 생각한다</button>`);}
// v0.5 Phase E: Aren's promotion rite and the Legion Drill (D-047). Conditions come from core/progression.
function showLegion(){if(!canStartSkirmish(state)){toast('ACT I을 마치고 재의 맹세를 정한 뒤 야영지에서 열 수 있습니다.');return;}
 const rows=HEROES.map(h=>{const rec=state.campaign.heroes.find(x=>x.id===h.id),st=trialState(state,h.id),t2=CLASS_TREE[h.id][1],act=CLASS_ACTIONS[t2.action];
  return `<div class="legion-row ${st.promoted?'done':''}">${portrait(state.units.find(u=>u.id===h.id)||rec,'card-sprite')}<div class="legion-info"><b>${esc(h.name)} <small>LV ${rec.level} · ${esc(classOf(rec)?.ko||'')}</small></b><span class="legion-path">${st.promoted?`✦ ${esc(t2.ko)} · ${esc(act.ko)}`:`→ ${esc(t2.ko)} · 새 행동 ${esc(act.ko)}`}</span>${st.promoted?'':`<span class="legion-checks">${st.checks.map(c=>`<i class="${c.ok?'ok':''}">${c.ok?'✓':'✗'} ${esc(c.label)}</i>`).join('')}</span>`}</div>${st.promoted?'<span class="legion-done">전직 완료</span>':`<button class="primary" data-do="trial-start" data-id="${h.id}" ${st.available?'':'disabled'}>시련</button>`}</div>`;}).join('');
 const drills=state.campaign.skirmishes?.drills||0;
 modal('군단장 아렌 · 전직과 훈련',`<p class="legion-intro">LV ${PROMOTION_LEVEL} 이상, 잠재력 3/3을 채운 장수는 시련을 이기면 전직합니다. 부족한 레벨과 잠재력은 군단 훈련에서 채울 수 있습니다.</p><div class="legion-list">${rows}</div><div class="legion-drill"><div><b>군단 훈련</b><p>다섯 장수 출전 · 반복 가능 · 경험치와 잠재력 기록이 그대로 남습니다 (지금까지 ${drills}회).</p></div><button class="primary" data-do="drill-start">훈련 출전</button></div>`,'');paintPortraits();}
function showCampaign(){modal('The Living Frontier',`<p>완료한 Mission은 연습으로 다시 출전합니다. 현재 전투 중이라면 스테이지 초기화로 재도전할 수 있습니다.</p>${Object.values(MISSIONS).map(m=>`<p><button data-do="choose-mission" data-id="${m.id}" ${m.id>1&&!state.campaign.completed.includes(m.id-1)?'disabled':''}>${String(m.id).padStart(2,'0')} · ${esc(m.title)} ${state.campaign.completed.includes(m.id)?'✓ 연습':''}</button></p>`).join('')}${LAST_MISSION<6?`<p class="muted">${String(LAST_MISSION+1).padStart(2,'0')} · 다음 업데이트 예정</p>`:''}`,'');}

function followAren(){} // MapCamera follows without DOM scrolling or scene teleportation.
function doorAtAren(){return !state.frontier.interior&&currentHub(state).places.find(p=>['weapon','item','enter'].includes(p.action)&&p.x===state.frontier.x&&p.y===state.frontier.y);}
function confirmEntrance(arg){const door=typeof arg==='string'?interactions(state).find(p=>p.action===arg):arg,kind=door?.action;if(state.frontier.interior||!door||!interactions(state).some(p=>p.id===door.id))return;doorStep=true;state.frontier.facing='up';const c=$('#frontier-map');if(c)drawHub(c,{...state,doorStep:true},{time:performance.now()});modal('건물 입장',`<p>${kind==='weapon'?'무기점':kind==='item'?'도구점':esc(door.name)}에 들어가시겠습니까?</p>`,frontierButton('enter-building','들어간다',kind==='enter'?door.buildingId:kind,false,'primary')+frontierButton('close-modal','취소'));}
function walkAren(dx,dy){if(frontierWalking||$('#modal-root').children.length||state.narrative.active)return false;if(!stepAren(state,dx,dy)){const door=doorAtAren();if(door&&dy<0)confirmEntrance(door);return false;}walkUntil=performance.now()+140;hubCamera.target=null;commit();const c=$('#frontier-map');if(c)drawHub(c,{...state,walking:true},{time:performance.now()});return true;}
async function walkToFrontier(x,y){if(frontierWalking||$('#modal-root').children.length||state.narrative.active)return;const door=!state.frontier.interior&&currentHub(state).places.find(p=>p.entrance&&p.entrance.tileX===x&&p.entrance.tileY===y);if(door){x=door.x;y=door.y;}const npc=currentHub(state).npcs.find(n=>n.x===x&&n.y===y);const path=npc?[[0,-1],[-1,0],[1,0],[0,1]].map(([dx,dy])=>frontierPath(state,x+dx,y+dy)).filter(Boolean).sort((a,b)=>a.length-b.length)[0]:frontierPath(state,x,y);if(!path){toast('건물과 사람을 피해 길 위의 목적지를 누르세요.');return;}frontierWalking=true;const epoch=navigationEpoch,startInterior=state.frontier.interior;try{for(const [a,b]of path.slice(1)){if(epoch!==navigationEpoch||state.frontier.interior!==startInterior||state.screen!=='exploration'||state.narrative.active||$('#modal-root').children.length)break;const f=state.frontier;stepAren(state,a-f.x,b-f.y);commit();const c=$('#frontier-map');if(c)drawHub(c,{...state,walking:true},{time:performance.now()});await new Promise(resolve=>setTimeout(resolve,75));}}finally{frontierWalking=false;render();}if(door&&!$('#modal-root').children.length&&state.frontier.x===door.x&&state.frontier.y===door.y)confirmEntrance(door);if(npc&&!$('#modal-root').children.length)await dispatch('npc',npc.id);}
document.addEventListener('click',e=>{if(e.target.id!=='frontier-map'||e.shiftKey||hubPanUsed){hubPanUsed=false;return;}const box=e.target.getBoundingClientRect(),point=hubCamera.tileAt(e.clientX-box.left,e.clientY-box.top);walkToFrontier(point.x,point.y);});
async function prepareCouncil(){
 heldMovement.clear();navigationEpoch++;while(frontierWalking)await new Promise(r=>setTimeout(r,16));
 if(state.frontier.interior){toast('건물 밖으로 나간 뒤 리아와 작전을 맞추세요.');return;}
 if(state.screen==='exploration'){
  if(!interactions(state).some(n=>n.id==='advisor'&&n.npc)){const n=currentHub(state).npcs.find(n=>n.id==='advisor');await walkToFrontier(n.x,n.y);}
  else await dispatch('npc','advisor');
  return;
 }
 if(openCouncil(state))commit();
}
function offerCouncilRecovery(){if(state.screen!=='exploration'||state.narrative.active||state.frontier.phase!=='preparation'||!interactions(state).some(n=>n.id==='advisor'&&n.npc))return;modal('작전 회의 복구','<p>작전 보고를 다시 확인합니다. 현재 장비와 임무 기록은 유지됩니다.</p>',frontierButton('advisor-recover','작전 회의를 다시 연다')+frontierButton('close-modal','돌아가기'));}
// M05 parley (C2): Baldrick's demand plays on the deployment screen, then Erik answers once.
// M06 aftermath: the Ashen Oath choice (C3), then the ACT I completion card. Both are one-time story beats.
function needsOath(){return state.missionId===6&&!state.practice&&state.screen==='exploration'&&state.frontier?.phase==='aftermath'&&state.campaign.flags.act1_completed&&!state.campaign.choices?.m06_oath;}
function oathFocus(){return {people:['사람','명령이 세지 않는 사람까지 지킨다'],comrades:['동료','누구도 두고 가지 않는다'],truth:['진실','지워진 서명의 끝까지 간다']};}
function offerOath(){if(!needsOath()||state.narrative.active||$('#modal-root').children.length)return;
 modal('재의 맹세',`<p>재의 군단은 무엇을 위해 싸우는가. 맹세의 중심을 정하세요. 어느 쪽이든 ACT I은 완결되며, 다음 이야기에서 동료들의 반응이 달라집니다.</p>`,Object.entries(oathFocus()).map(([id,[name,line]])=>frontierButton('oath-pick',`<b>${name}</b> — ${line}`,id,false,'primary')).join(''));}
function offerAct1(){if(state.missionId!==6||state.practice||!state.campaign.choices?.m06_oath||state.campaign.choices.act1_seen||state.narrative.active||state.screen!=='exploration'||$('#modal-root').children.length)return;
 state.campaign.choices.act1_seen='yes';save();const [name]=oathFocus()[state.campaign.choices.m06_oath]||['동료'];
 modal('ACT I 완료',`<div class="act1-card"><div class="eyebrow">ACT I · THE BROKEN ALLEGIANCE</div><h2>재의 군단</h2><p class="act1-en">Ashen Legion</p><p>왕실 군령부의 봉쇄 명령을 거부하고, 피난민과 함께 국경 관문을 넘었다. 수비대는 오늘부터 독립 군단이다.</p><p class="act1-oath">맹세의 중심 · <b>${esc(name)}</b></p><blockquote>「아렌 발터. 자네의 질서가 얼마나 버티는지 지켜보겠다.」<cite>— 발드릭 로엔의 서신</cite></blockquote><p class="act1-next">ACT II · 세 개의 깃발 — 북쪽 철관성으로</p></div>`,frontierButton('close-modal','야영지로','',false,'primary'));}
// v0.5 Phase F: once a promotion scene has played, Aren's rank is shown as a card (before → after).
function offerPromotion(){if(state.screen!=='exploration'||state.practice||state.narrative.active||$('#modal-root').children.length)return;const c=state.campaign;
 const id=Object.keys(c.promotions||{}).find(h=>state.narrative.seen?.includes(`promo:${h}`)&&!c.choices?.[`promo_card_${h}`]);if(!id)return;
 c.choices??={};c.choices[`promo_card_${id}`]='seen';save();const [t1,t2]=CLASS_TREE[id],act=CLASS_ACTIONS[t2.action],u=findUnit(state,id)||c.heroes.find(h=>h.id===id),label={maxHP:'HP',atk:'ATK',def:'DEF',mag:'MAG',res:'RES',spd:'SPD',mov:'MOV'};
 const bonus=Object.entries(t2.bonus||{}).map(([k,v])=>`<i>${label[k]||k.toUpperCase()} +${v}</i>`).join('')+(t2.movBonus?`<i>MOV +${t2.movBonus}</i>`:'');
 modal('전직',`<div class="promo-card"><div class="eyebrow">PROMOTION · 재의 군단</div><div class="promo-busts"><canvas class="promo-bust before" width="360" height="440" data-promo="1" aria-label="${esc(t1.ko)}"></canvas><span class="promo-arrow" aria-hidden="true">➜</span><canvas class="promo-bust after" width="360" height="440" data-promo="2" aria-label="${esc(t2.ko)}"></canvas></div><h2>${esc(u.name)} · ${esc(t2.ko)}</h2><p class="promo-en">${esc(t1.name)} → ${esc(t2.name)}</p><div class="promo-action"><b>새 행동 · ${esc(act.ko)}</b><p>${esc(act.note)}</p></div>${t2.skillNote?`<p class="promo-note">${esc(t2.skillNote)}</p>`:''}${bonus?`<p class="promo-bonus">${bonus}</p>`:''}</div>`,frontierButton('close-modal','군단으로','',false,'primary'));
 document.querySelectorAll('[data-promo]').forEach(cv=>{const tier=+cv.dataset.promo;drawBust(cv.getContext('2d'),{...u,classTier:tier},{expression:tier===2?'determined':'neutral',missionId:state.missionId});});audio.select('rite');}
// v0.6 Phase D choices: M07 captured deserters (camp, after the battle), M08 command order (deployment, like the M05 parley).
const needsDeserters=()=>state.missionId===7&&!state.practice&&state.frontier?.phase==='aftermath'&&!!state.campaign.flags.mission_07_deserter_captured&&!state.campaign.choices?.m07_deserters;
function showDeserterChoice(){if(!needsDeserters())return;modal('탈영병의 처분',`<p>붙잡은 탈영병 대장과 부하들을 어떻게 할까요? 어느 쪽이든 이야기는 이어지며, 철왕관의 신뢰와 동료들의 반응이 달라집니다.</p>`,`<button class="primary" data-do="deserters-pick" data-id="handover">통령국에 넘긴다 — 이 땅의 법을 따른다</button><button class="primary" data-do="deserters-pick" data-id="legion">군단이 데려간다 — 진영에서 일하게 한다</button><button data-do="close-modal">조금 더 생각한다</button>`);}
const needsOrder=()=>state.missionId===8&&!state.practice&&!state.campaign.choices?.m08_order;
function offerOrder(){if(state.screen!=='deployment'||!needsOrder()||state.narrative.active||$('#modal-root').children.length)return;
 if(!state.narrative.events.includes('8:order')){enqueueStory(state,'8:order');openStory(state);commit();return;}
 modal('사령부 명령',`<p>발드릭이 봉인된 명령서를 펼친다. 「TURN 6에 후위 마을을 포기하고 협곡을 사수하라.」 군단은 어떻게 할까요?</p>`,frontierButton('order-pick','<b>명령을 따른다</b> — 협곡 사수, TURN 6에 후위 마을 포기','hold',false,'primary')+frontierButton('order-pick','<b>구출조를 보낸다</b> — 협곡을 지키며 후위 마을 주민 구출','rescue'));}
// Thea joins after M08 (D-055 §5): once her scene has played, a card shows her joining the legion.
function offerRecruitCard(){const c=state.campaign;if(state.screen!=='exploration'||state.practice||state.narrative.active||$('#modal-root').children.length||!c.roster?.includes('thea')||!state.narrative.seen?.includes('after:8:thea:joined')||c.choices?.recruit_card_thea)return;
 c.choices.recruit_card_thea='seen';save();const u=findUnit(state,'thea')||c.heroes?.find(h=>h.id==='thea');
 modal('새 동료',`<div class="promo-card"><div class="eyebrow">NEW COMRADE · 재의 군단</div><div class="promo-busts"><canvas class="promo-bust after" width="360" height="440" data-recruit="thea" aria-label="테아"></canvas></div><h2>테아 · 기병 창기사</h2><p class="promo-en">Thea · Lancer · LV ${u?.level||8}</p><div class="promo-action"><b>돌격 (Charge)</b><p>근접 공격 피해 +4. 이번 턴 3칸 이상 달린 뒤 쓰면 피해 +3 더, 반격을 받지 않습니다. 기병이라 이동 5, 숲 1, 산길·지붕은 들어갈 수 없습니다.</p></div><p class="promo-note">다음 전투부터 출전 6명 중 한 자리를 맡을 수 있습니다.</p></div>`,frontierButton('close-modal','군단으로','',false,'primary'));
 document.querySelectorAll('[data-recruit]').forEach(cv=>drawBust(cv.getContext('2d'),u||{id:'thea'},{expression:'determined',missionId:state.missionId}));}
const needsParley=()=>state.missionId===5&&!state.practice&&!state.campaign.choices?.m05_erik_answer;
function offerParley(){if(state.screen!=='deployment'||!needsParley()||state.narrative.active||$('#modal-root').children.length)return;
 if(!state.narrative.events.includes('5:parley')){enqueueStory(state,'5:parley');openStory(state);commit();return;}
 modal('에릭의 대답',`<p>발드릭이 에릭을 똑바로 바라본다. 어떻게 답할까요? 어느 쪽이든 전투로 이어지며, 퇴각 장면과 야영지 대화가 달라집니다.</p>`,frontierButton('parley-pick','“구해 주신 목숨입니다. 그날을 잊은 적은 없습니다.”','acknowledged',false,'primary')+frontierButton('parley-pick','“지금 제 곁에 있는 동료들이 제 대답입니다.”','present'));}
function offerAdvisor(){
 const f=state.frontier;if(state.screen!=='exploration'||!f.advisorPending||state.narrative.active||$('#modal-root').children.length)return;
 if(!interactions(state).some(n=>n.id==='advisor'&&n.npc)){f.advisorPending=false;syncFrontier(state);save();return;}
 const done=f.phase==='aftermath';
 modal('군사 리아',`<div class="strategist-line">${portrait(state.units.find(u=>u.id==='lia'),'card-sprite')}<p>${done?state.missionId===LAST_MISSION?'협곡을 지켰어요. 다음은 서쪽, 자유도시 벨마르예요. M09 자유의 도시는 다음 업데이트에서 이어져요.':'동료들 먼저 둘러보고, 다음 이야기를 골라요.':'에릭, 작전 회의 시작할까요?'}</p></div>`,
 (!done?frontierButton('advisor-operation','다음 작전을 듣는다','',false,'primary'):'')+frontierButton('mission-status','현재 임무를 확인한다')+frontierButton('close-modal','아직 준비가 필요하다'));
}

// v0.5 hubs (D-052): camp-type hubs trade at open-air stalls (no shop interior); the wandering merchant sells both.
const stallNPC=()=>state.frontier.interior?null:interactions(state).find(n=>n.npc&&(n.service||n.services));
function shopAccess(kind){const f=state.frontier;return state.screen==='exploration'&&!!kind&&(f.interior?f.interior===kind:interactions(state).some(n=>n.npc&&(n.service===kind||n.services?.includes(kind))));}
function openStall(n){if(!n?.services||!n.services.every(shopAccess))return;shopKind='item';lastShop=null;modal(n.name.split(' · ')[0],stallHTML(),'');audio.select('shop');}
function openShopkeeper(kind){if(!shopAccess(kind))return;const n=stallNPC();if(n?.services){openStall(n);return;}shopKind=kind;lastShop=kind;modal(n?n.name.split(' · ')[0]:kind==='weapon'?'대장장이':'도구 상인',shopkeeperHTML(kind),'');audio.select('shop');}
function openShop(kind,mode=shopMode){if(!shopAccess(kind))return;shopKind=kind;lastShop=kind;shopMode=mode;modal(kind==='weapon'?'Blacksmith · 무기점':'Item Shop · 도구점',mode==='buy'?shopHTML(state,kind,esc):ownedShopHTML(state,mode),`<button data-do="shop-owner">주인에게 돌아가기</button><button data-do="inventory">Party / 장비</button><button data-do="items">Inventory</button>`);audio.select('shop');}
function showInventory(id){if(!['exploration','warroom','deployment'].includes(state.screen)){toast('전투 전 준비 단계에서 장비를 바꿀 수 있습니다.');return;}shopKind=null;const hero=partyHeroes(state.campaign).some(h=>h.id===id)?id:ui.selected;ui.selected=hero;modal('Party · Equipment',inventoryHTML(state,hero,esc,portrait),'');paintPortraits();}
function showItems(sel=null){const e=state.economy,ids=Object.keys(TOOLS),bag=ids.flatMap(id=>Array.from({length:e.items[id]},()=>id)),pick=sel&&TOOLS[sel]?sel:bag[0]||ids[0],t=TOOLS[pick];
 const slots=Array.from({length:6},(_,i)=>bag[i]?`<button class="bag-slot ${bag[i]===pick?'active':''}" data-do="item-detail" data-id="${bag[i]}" aria-label="${esc(TOOLS[bag[i]].name)}">${itemIcon(bag[i],40)}</button>`:'<div class="bag-slot empty" aria-hidden="true"></div>').join('');
 const owner=id=>Object.entries(e.equipped).find(([,slots])=>Object.values(slots).includes(id))?.[0];
 const gear=e.gear.length?e.gear.map(g=>{const who=owner(g.id);return `<div class="gear-cell" title="${esc(GEAR[g.type].name)}">${itemIcon(g.type,32)}${g.level?'<i>+1</i>':''}${who?`<em>${esc(findUnit(state,who).name)}</em>`:''}<small>${esc(GEAR[g.type].name)}</small></div>`;}).join(''):'<p class="muted">보관 중인 장비가 없습니다.</p>';
 modal('Inventory · 소지품',`<div class="bag-head"><span>${itemIcon('gold',26)}<b>${e.gold}</b> Gold</span><span>도구 <b>${itemCount(e)}</b>/6</span><span>${itemIcon('potion',22)} 기본 회복약 <b>${state.potions}</b>/2</span></div><div class="bag-layout"><div><div class="bag-label">가방</div><div class="bag-grid">${slots}</div><div class="bag-counts">${ids.map(id=>`<button class="bag-count ${id===pick?'active':''}" data-do="item-detail" data-id="${id}">${itemIcon(id,26)}<b>×${e.items[id]}</b></button>`).join('')}</div></div><div class="item-detail">${itemIcon(pick,56)}<div><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><small>구매 ${t.price} Gold · 판매 ${t.sell} Gold · 보유 ${e.items[pick]}</small></div></div></div><div class="bag-label">장비 보관함 ${e.gear.length}/24</div><div class="gear-grid">${gear}</div>${e.rewardPending.length?`<p class="bag-pending">보관 보상: ${e.rewardPending.map(rewardLabel).join(' / ')}</p>${frontierButton('transaction','빈 공간으로 보상 받기','collect-rewards|')}`:''}<p class="muted">도구는 공용 가방에 최대 6개. 전투에서 선택한 장수가 자신에게 사용합니다(이동 후 가능, 행동 1회). Retry/Stage Restart는 출전 직전 수량으로 돌아갑니다.</p>`,'');}
function compareGear(type,hero,instanceId=null){const g=GEAR[type],u=findUnit(state,hero);if(!g||!u)return '';const e=structuredClone(state.economy);let instance=e.gear.find(a=>a.id===instanceId);if(!instance){instance={id:'preview',type,level:0};e.gear.push(instance);}const before=effectiveStats(state,u);e.equipped[hero][g.slot]=instance.id;const after=effectiveStats({...state,economy:e},u);return `<p>${g.icon} <b>${g.name} ${instance.level?'+1':''}</b><br>${g.description}</p><p>비교: ${u.name} · 현재 ${g.slot} → 후보<br>${['atk','def','mag','res','spd','mov','hit'].map(k=>{const a=before[k]||0,b=after[k]||0,d=b-a;return `<span class="stat-delta">${k.toUpperCase()} ${a} → ${b} <b class="${d<0?'negative':'positive'}">(${d>0?'+':''}${d})</b></span>`;}).join('')}<br>사거리 ${u.range.join('–')} → ${u.range.join('–')} (0) · 지형 회피 변화 0<br>HIT 보너스 ${before.hit||0} → ${after.hit||0}</p><p>${g.heroes.includes(hero)?'병종 호환 · 구매 확정 시 선택 장수에게 장착':'병종 불일치 · 선택할 수 없습니다.'}</p>`;}
function transactionPreview(encoded){if(state.practice){toast('연습에서는 정식 자산 거래를 하지 않습니다.');return;}const shopReturn=!!(lastShop&&shopAccess(lastShop));const [op,id,hero]=encoded.split('|'),g=state.economy.gear.find(a=>a.id===id);const req={op,id,hero,slot:op==='unequip'?id:op==='equip'?GEAR[g?.type]?.slot:null,token:`tx:${state.economy.nonce}`};const amount=op==='buy-item'?TOOLS[id]?.price:op==='sell-item'?-TOOLS[id]?.sell:op==='buy-gear'?GEAR[id]?.price:op==='upgrade'?40:op==='sell-gear'?-Math.floor((GEAR[g?.type]?.price||0)*.4):0;
 modal('거래 확인',`<p>${esc({ 'collect-rewards':'보관 보상 받기','buy-item':'도구 구매','sell-item':'도구 판매','buy-gear':'장비 구매','sell-gear':'장비 판매',upgrade:'장비 +1 강화',equip:'장비 장착',unequip:'기본 장비로 복귀'}[op]||op)} · ${esc(TOOLS[id]?.name||GEAR[id]?.name||GEAR[g?.type]?.name||id)}</p>${op==='upgrade'?`<p>강화 0 → +1 · ${bonusText(GEAR[g.type].upgrade)}<br>소유 장비 1개에 한 번만 적용됩니다.</p>`:''}<p>Gold ${state.economy.gold} → ${state.economy.gold-amount}${amount>0?` (−${amount})`:amount<0?` (+${-amount})`:''}</p>`,`<button class="primary" data-do="confirm-transaction">확정</button><button data-do="${shopReturn?'shop-back':'close-modal'}">취소</button>`);pendingTransaction=req;
}
async function frontierDispatch(action,id=''){
 const allowed=['advisor-locate','advisor-operation','advisor-recover','advisor-menu','mission-status','shop-service','stall-service','shop-owner','enter-building','hub-zoom','hub-focus','shop-exit','purchase-hero','shop-back','walk','interact','npc','place','fast-map','fast-travel','hub-return','aftermath','affiliate','inventory','items','transaction','confirm-transaction','buy-preview','gear-info','gear-compare','tool','tool-confirm'];if(!allowed.includes(action))return false;
 if(frontierWalking&&!['items','inventory'].includes(action)){navigationEpoch++;while(frontierWalking)await new Promise(r=>setTimeout(r,16));}
 const f=ensureFrontier(state);
 if(action==='advisor-locate')await prepareCouncil();
 if(action==='advisor-operation'){if(openCouncil(state)){closeModal();commit();}else offerCouncilRecovery();}
 if(action==='advisor-recover'){if(recoverCouncil(state)){closeModal();commit();}}
 if(action==='mission-status'){const intel=councilInfo(state);modal('현재 임무',`<p>${esc(missionOf(state).title)}</p><p>${f.phase==='aftermath'?state.missionId===LAST_MISSION?'ACT II 전반 · 회색 협곡 사수. 다음 이야기 M09 자유의 도시 — 다음 업데이트.':'전투를 마쳤습니다. 동료를 살핀 뒤 다음 이야기를 선택하세요.':esc(intel.plan)}</p>`,frontierButton('advisor-menu','작전 대화로 돌아가기'));}
 if(action==='advisor-menu'){closeModal();offerAdvisor();}
 if(action==='enter-building'){closeModal();if(enterInterior(state,id)){hubCamera.reset();commit();}}
 if(action==='walk'){const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[id];if(d)walkAren(...d);}
 if(action==='interact'){const n=interactions(state)[0];if(n)await dispatch(n.npc?'npc':'place',n.id);else toast('대화할 사람이나 입구 가까이 이동하세요.');}
 if(action==='npc'){const n=interactions(state).find(n=>n.id===id&&n.npc);if(n?.services){openStall(n);return true;}if(n?.service){openShopkeeper(n.service);return true;}if(interactNPC(state,id)){commit();}else if(id==='advisor')offerCouncilRecovery();}
 if(action==='affiliate'){if(affiliate(state,id)){closeModal();commit();toast(`${SPEAKERS[id].name} · 소속 기록을 남겼습니다.`);}}
 if(action==='place'){const n=interactions(state).find(p=>!p.npc&&p.id===id);if(n?.action==='council')await prepareCouncil();else if(n?.action==='exit'){if(exitInterior(state)){hubCamera.reset();commit();}}else if(['weapon','item','enter'].includes(n?.action))confirmEntrance(n);else if(n?.action==='chest'){const full=itemCount(state.economy)>=6,r=openChest(state,n.chestId,transact);if(r.ok){const w=r.reward;modal('보물상자',`<div class="chest-find">${itemIcon(w.kind==='gold'?'gold':w.kind==='item'?w.type:'potion',48)}<p>${w.kind==='gold'?`<b>${w.amount} Gold</b>를 찾았다!`:w.kind==='item'?`<b>${esc(TOOLS[w.type].name)}</b>을(를) 찾았다!${full?' 가방이 가득 차서 대신 20 Gold를 챙겼다.':''}`:'먼지와 거미줄뿐이다…'}</p></div>`,frontierButton('close-modal','확인','',false,'primary'));audio.select('shop');commit();}else toast(r.error);}}
 if(action==='fast-map'){modal('Town Map · 방문한 장소',`<p>직접 찾아간 주요 장소에 빠르게 이동합니다.</p><div class="travel-list">${HUBS[f.hub].places.map(p=>frontierButton('fast-travel',`${p.name} ${f.visited[f.hub].includes(p.id)?'✓':'· 미방문'}`,p.id,!f.visited[f.hub].includes(p.id))).join('')}</div>`,'');}
 if(action==='fast-travel'){if(fastTravel(state,id)){closeModal();commit();}}
 if(action==='inventory')showInventory(id);
 if(action==='items')showItems();
 if(action==='hub-return'&&['warroom','deployment','exploration'].includes(state.screen)){closeModal();enterHub(state,{aftermath:f.phase==='aftermath',story:false});ui.menu=null;commit();}
 if(action==='aftermath'&&state.screen==='result'&&state.skirmish){closeModal();state=returnToCamp(state);ui.selected='eric';ui.mode='choose';ui.menu=null;ui.preview=null;renderer.clearPresentation();renderer.reset();openStory(state);commit();return true;}
 if(action==='aftermath'&&state.screen==='result'){closeModal();if(state.outcome==='defeat'){state=replay(state);enterHub(state,{story:false});}else{if(state.practice)state.economy=structuredClone(state.campaign.economy);enterHub(state,{aftermath:true});}ui.menu=null;ui.preview=null;renderer.clearPresentation();commit();}
 if(action==='buy-preview'){const type=id.split('|')[0];showPurchase(type,null);}
 if(action==='purchase-hero'){const [type,hero]=id.split('|');showPurchase(type,hero);}
 if(action==='shop-owner')openShopkeeper(lastShop||f.interior);
 if(action==='shop-service'){const kind=lastShop||f.interior;if(['buy','sell','upgrade'].includes(id)&&!(id==='upgrade'&&kind!=='weapon'))openShop(kind,id);}
 if(action==='stall-service'){const [kind,mode]=id.split('|');if(['buy','sell','upgrade'].includes(mode)&&!(mode==='upgrade'&&kind!=='weapon'))openShop(kind,mode);}
 if(action==='shop-back')openShop(lastShop||state.frontier.interior);
 if(action==='hub-zoom')hubCamera.zoomBy(id==='in'?1.15:1/1.15);
 if(action==='hub-focus')hubCamera.focus(f.x,f.y);
 if(action==='shop-exit'){const exit=currentHub(state).places.find(p=>p.action==='exit');if(exit){await walkToFrontier(exit.x,exit.y);if(exitInterior(state)){hubCamera.reset();commit();}}}
 if(action==='gear-info'){const [type,hero]=id.split('|');modal('Equipment Comparison',compareGear(type,hero),'');}
 if(action==='gear-compare'){const [instance,hero]=id.split('|'),g=state.economy.gear.find(a=>a.id===instance);if(g)modal('Equipment Comparison',compareGear(g.type,hero,instance),'');}
 if(action==='transaction')transactionPreview(id);
 if(action==='confirm-transaction'&&pendingTransaction){const req=pendingTransaction;pendingTransaction=null;const before=structuredClone(state),result=transact(state,req);if(result.ok){const saved=save();if(!saved.ok){state=before;closeModal();render();toast('거래를 적용하지 않았습니다. 저장이 실패하여 이전 자산을 유지합니다.');}else{closeModal();commit();if(lastShop&&shopAccess(lastShop))openShop(lastShop);toast('거래 완료 · 자산과 장비를 저장했습니다.');}}else toast(result.error);}
 if(action==='tool'){const t=TOOLS[id],u=findUnit(state,ui.selected);if(t&&canAct(state,u))modal('도구 사용',`<p>${u.name} · ${t.name}<br>${t.description}<br>보유 ${state.economy.items[id]} · 이동 후 사용 가능, 행동을 마칩니다.</p>`,frontierButton('tool-confirm','사용 확정',id,false,'primary'));}
 if(action==='tool-confirm'){closeModal();await execute(`tool:${id}`);}
 return true;
}

function offerAffiliation(){const candidate=state.frontier?.pendingRecruit;if(state.screen!=='exploration'||state.narrative.active||!candidate||$('#modal-root').children.length)return;if(state.frontier.affiliation[candidate]!=='encountered')return;modal('동료의 약속',`<p>${esc(SPEAKERS[candidate]?.ko)}의 협력을 받아들이겠습니까? 기존 다섯 명의 출전은 유지됩니다. 이 선택은 동료의 소속 기록을 남깁니다.</p>`,`<button class="primary" data-do="affiliate" data-id="${candidate}">함께한다</button><button data-do="close-modal">나중에 이야기</button>`);}

function persistUIPrefs(){try{storage.setItem('ashen-crown:ui:v1',JSON.stringify({speed:ui.speed,movement:ui.movement,reduced:ui.reduced,questClosed:ui.questClosed}));}catch{}}
function renderObjectives(){const f=state.frontier,explore=state.screen==='exploration',panel=$('#quest-panel');panel.hidden=!['exploration','battle','deployment'].includes(state.screen);const rescued=state.units.filter(u=>u.team==='civilian'&&u.rescued).length;$('#quest-content').innerHTML=explore?questExplore():`<b>${esc(missionOf(state).title)}</b><p>${esc(missionOf(state).objective)}</p><p class="quest-status">${rulesOf(state)?esc(rulesOf(state).status(state)):state.missionId===2?'생포 '+(findUnit(state,'boss').rescued?'✓':'◇'):`구조 ${rescued}/${missionOf(state).civilians.length}`}</p>`;}
function showPurchase(type,hero){const gear=GEAR[type];if(!gear)return;shopKind='weapon';const u=findUnit(state,hero);modal('장비 선택 → 장수 선택',`<div class="purchase-layout"><article><h3>${gear.icon} ${gear.name}</h3><p>${gear.description}</p><p>${gear.price} Gold · ${gear.slot}</p><p>사용 병종: ${gear.heroes.map(id=>findUnit(state,id).className).join(', ')}</p></article><div class="purchase-roster">${HEROES.map(h=>`<button data-do="purchase-hero" data-id="${type}|${h.id}" ${gear.heroes.includes(h.id)?'':'disabled'} class="${h.id===hero?'active':''}">${portrait(findUnit(state,h.id),'card-sprite')}<span>${h.name}<small>${h.className} · ${gear.heroes.includes(h.id)?'장착 가능':'병종 사용 불가'}</small></span></button>`).join('')}</div><article>${u?portrait(u)+`<h3>${u.name}</h3><p>${esc(equipmentLabel(state.economy,hero))}</p>`+compareGear(type,hero):''}</article></div>`,`<button class="primary" data-do="transaction" data-id="buy-gear|${type}|${hero}" ${!gear.heroes.includes(hero)||state.economy.gold<gear.price?'disabled':''}>${gear.price} Gold · ${u?.name||'장수 선택'} 구매 및 장착 확인 →</button><button data-do="shop-back">취소 / 상품 목록</button>`);paintPortraits();}
function frontierFrame(time){heldMovement.tick(time,state.screen==='exploration'&&!state.narrative.active&&!$('#modal-root').children.length&&!frontierWalking);const canvas=$('#frontier-map');if(canvas&&state.screen==='exploration')drawHub(canvas,{...state,doorStep:doorStep&&!state.frontier.interior,walking:!ui.reduced&&(frontierWalking||time<walkUntil)},{time:ui.reduced?0:time});const stage=$('#scene-stage');if(stage)drawHub(stage,state,{line:storyLine(state),time:ui.reduced?0:time});const ws=$('#world-stage');if(ws){const l=storyLine(state);if(l?.world)drawWorld(ws,{campaign:state.campaign,world:l.world,time:ui.reduced?worldStart.time+5000:time,start:worldStart.time,hub:state.frontier?.hub});}const wv=$('#world-view');if(wv)drawWorld(wv,{campaign:state.campaign,world:{focus:'east',to:state.frontier?.hub},time,start:0,hub:state.frontier?.hub});requestAnimationFrame(frontierFrame);}requestAnimationFrame(frontierFrame);
let hubDrag=null,hubPanUsed=false;
document.addEventListener('pointerdown',e=>{if(e.target.id==='frontier-map'&&(e.shiftKey||e.button===2)){hubDrag={x:e.clientX,y:e.clientY};e.preventDefault();}});
document.addEventListener('pointermove',e=>{if(hubDrag){hubPanUsed=true;hubCamera.panBy(e.clientX-hubDrag.x,e.clientY-hubDrag.y);hubDrag={x:e.clientX,y:e.clientY};}});
document.addEventListener('pointerup',()=>hubDrag=null);
document.addEventListener('contextmenu',e=>{if(e.target.id==='frontier-map')e.preventDefault();});
document.addEventListener('wheel',e=>{if(e.target.id==='frontier-map'){e.preventDefault();hubCamera.zoomBy(e.deltaY<0?1.08:1/1.08);}},{passive:false});

document.addEventListener('keyup',e=>heldMovement.release('key:'+e.code,performance.now()));
window.addEventListener('blur',()=>heldMovement.clear());
document.addEventListener('visibilitychange',()=>{if(document.hidden)heldMovement.clear();});
let walkPointer=null;
document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-do="walk"]');if(!b||walkPointer!==null)return;e.preventDefault();walkPointer=e.pointerId;try{document.body.setPointerCapture(e.pointerId);}catch{}const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[b.dataset.id];if(d)heldMovement.press('pointer',d,performance.now());},{passive:false});
for(const event of ['pointerup','pointercancel','lostpointercapture'])window.addEventListener(event,e=>{if(e.pointerId===walkPointer&&(event!=='lostpointercapture'||e.target===document.body)){walkPointer=null;heldMovement.release('pointer',performance.now());}});
